// ============================================================================
// FAO Reserve Reconciliation Agent — Init Execution
// ----------------------------------------------------------------------------
// FAO-GOV-008: Generate correlation_id and execution_id at execution start.
// Both are UUIDs threaded through every event for this run.
//
// FIXTURE DESIGN (calibrated against Kraken Dec 2025 PoR + control coverage):
//   BTC, ETH, XRP — wallet/ledger calibrated to Kraken's published Dec 31, 2025
//                   PoR ratios (1.003, 1.013, 1.006 respectively).
//   USDC          — clean exact-match baseline.
//   USDT          — synthetic anomaly: stablecoin USD-materiality breach
//                   (FAO-REC-002).
//   SOL           — synthetic anomaly: under-reservation floor violation
//                   (FAO-REC-004).
//   ADA           — synthetic anomaly: negative liability — krakendb 2014
//                   precedent (FAO-REC-007).
//
// Source URL for real-anchored assets:
//   https://blog.kraken.com/news/december-2025-proof-of-reserves
//
// In production, wallet_data comes from Fireblocks API and ledger_data from
// NetSuite GL. Inline embedding here isolates policy logic from data-source
// plumbing for the smoke test; file reads / API calls move in post-launch.
// ============================================================================

// UUID v4 generator — inline implementation to avoid n8n's sandbox restriction
// on require('crypto'). Cryptographically adequate for correlation/execution
// IDs (Math.random is sufficient here; we're not signing anything).
const randomUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const correlation_id = randomUUID();
const execution_id   = randomUUID();
const agent_id       = 'fao_reserve_recon_v1';
const risk_tier      = 'RED';

// --- Fixture: simulated on-chain wallet holdings (Fireblocks proxy) -------
const wallet_data = {
  BTC:  167690.25,        // anchored to Kraken Dec 2025 PoR (ratio 1.003)
  ETH:  2884112,          // anchored to Kraken Dec 2025 PoR (ratio 1.013)
  USDC: 891723456,        // synthetic clean exact-match baseline
  USDT: 1234567890.50,    // synthetic stablecoin USD-materiality anomaly
  SOL:  8740000,          // synthetic under-reservation anomaly (ratio 0.95)
  XRP:  128265000,        // anchored to Kraken Dec 2025 PoR (ratio 1.006)
  ADA:  47293847          // wallet positive; ledger intentionally negative
};

// --- Fixture: simulated internal client-liability ledger (NetSuite proxy) -
const ledger_data = {
  BTC:  167188.68,
  ETH:  2847100,
  USDC: 891723456,
  USDT: 1234500000,
  SOL:  9200000,
  XRP:  127500000,
  ADA:  -150000           // FAO-REC-007 trigger, krakendb 2014 precedent
};

// --- Fixture provenance metadata (threaded into shadow_ledger evidence) ---
// Self-identifying provenance per asset so every ledger row carries the
// source of truth used. Auditor query:
//   SELECT inputs->>'asset', inputs->'fixture_metadata'->>'source'
//   FROM shadow_ledger;
const fixture_metadata = {
  BTC:  { source: 'kraken_por_2025_q4_anchor',  reference_url: 'https://blog.kraken.com/news/december-2025-proof-of-reserves', notes: 'Wallet/ledger calibrated to published Dec 31 2025 ratio 100.3%' },
  ETH:  { source: 'kraken_por_2025_q4_anchor',  reference_url: 'https://blog.kraken.com/news/december-2025-proof-of-reserves', notes: 'Wallet/ledger calibrated to published Dec 31 2025 ratio 101.3%' },
  USDC: { source: 'synthetic_clean_baseline',   notes: 'Exact match — exercises the in-band ALLOW path with zero discrepancy' },
  USDT: { source: 'synthetic_anomaly',          control: 'FAO-REC-002', notes: 'Stablecoin USD-materiality breach: ratio in band but absolute USD discrepancy exceeds threshold' },
  SOL:  { source: 'synthetic_anomaly',          control: 'FAO-REC-004', notes: 'Under-reservation: ratio 0.95 below floor 1.00' },
  XRP:  { source: 'kraken_por_2025_q4_anchor',  reference_url: 'https://blog.kraken.com/news/december-2025-proof-of-reserves', notes: 'Wallet/ledger calibrated to published Dec 31 2025 ratio 100.6%' },
  ADA:  { source: 'synthetic_anomaly',          control: 'FAO-REC-007', notes: 'Negative liability — krakendb 2014 reference implementation precedent' }
};

const asset_count = Object.keys(wallet_data).length;

return [{
  json: {
    // --- Writer payload (17-field schema per Writer sub-workflow) -----------
    correlation_id,
    execution_id,
    agent_id,
    risk_tier,
    inputs: {
      event_type:        'STARTED',
      asset_scope:       Object.keys(wallet_data),
      asset_count:       asset_count,
      wallet_source:     'fixture://wallet_data.json (Fireblocks proxy)',
      ledger_source:     'fixture://ledger_data.json (NetSuite proxy)',
      fixture_provenance: fixture_metadata
    },
    ai_prompt:           null,
    ai_output:           null,
    ai_confidence:       null,
    fractional_cost_usd: null,
    policy_outcome:      'ALLOW',
    policy_sub_tier:     null,
    policy_rationale:    `FAO-REC-001 ${agent_id} execution started. Reconciling ${asset_count} assets (${Object.keys(wallet_data).join(', ')}) against materiality thresholds. Risk tier: ${risk_tier}. Fixture mix: 3 Kraken Dec 2025 PoR anchors + 1 clean baseline + 3 synthetic control anomalies.`,
    obligations:         [],
    hitl_status:         'NOT_REQUIRED',
    hitl_approver_id:    null,
    status:              'SUCCESS',
    error_details:       null,

    // --- Internal context (underscore prefix; ignored by autoMapInputData) --
    _wallet_data:      wallet_data,
    _ledger_data:      ledger_data,
    _fixture_metadata: fixture_metadata
  }
}];

// ============================================================================
// FAO Reserve Reconciliation Agent — Per-Asset Reconcile (observe + decide)
// ----------------------------------------------------------------------------
// Controls implemented:
//   FAO-REC-002  Per-Asset Materiality Threshold Evaluation
//   FAO-REC-004  Reserve Ratio Threshold Check
//   FAO-REC-006  Expected-Ratio Band Evaluation
//   FAO-REC-007  Negative Liability Detection (krakendb precedent)
//
// Design note: COMPARED and POLICY_DECIDED collapsed into a single
// ASSET_RECONCILED event per asset. Reasons:
//   1. shadow_ledger.policy_outcome is NOT NULL — a separate COMPARED row
//      would force a placeholder policy_outcome which is misleading.
//   2. Observation and decision happen atomically; no time gap an auditor
//      cares about exists between them.
//   3. One row per asset = complete story per asset = cleaner audit grain.
//
// Decision matrix (deterministic, evaluated top-down — first match wins):
//   1. ledger < 0           → REQUIRE_HUMAN CRITICAL (FAO-REC-007)
//   2. ledger == 0          → REQUIRE_HUMAN STANDARD (cannot compute ratio)
//   3. ratio < floor        → REQUIRE_HUMAN CRITICAL (under-reserved)
//   4. ratio > band_upper   → REQUIRE_HUMAN STANDARD (unexpected surplus)
//   5. Stablecoin AND |discrepancy| > materiality_usd
//                            → REQUIRE_HUMAN STANDARD (USD threshold breach)
//   6. ratio < band_lower   → ALLOW_WITH_OBLIGATIONS (drift below band)
//   7. otherwise            → ALLOW (in expected band)
//
// Note on USD materiality test: applied only to stablecoins because for
// stablecoins, raw units == USD value (1 USDC = $1). For non-stablecoins,
// applying USD materiality requires a price oracle which is out of scope
// for tonight. Tomorrow's AI advisory wiring (Apr 25) can flag suspicious
// non-stablecoin discrepancies advisorially.
// ============================================================================

const ctx       = $('Init Execution').first().json;
const wallet    = ctx._wallet_data;
const ledger    = ctx._ledger_data;
const threshold_rows = $input.all().map(item => item.json);

// Build asset_symbol → threshold lookup
const threshold_by_asset = {};
for (const t of threshold_rows) {
  threshold_by_asset[t.asset_symbol] = t;
}

const output_items = [];

for (const asset of Object.keys(wallet)) {
  const w = wallet[asset];
  const l = ledger[asset];
  const t = threshold_by_asset[asset];

  // Defensive: asset present in fixture but not in materiality_thresholds.
  // Should not happen with current seed but worth guarding for robustness.
  if (!t) {
    output_items.push({ json: build_writer_payload(ctx, {
      asset, wallet: w, ledger: l,
      ratio: null, discrepancy: null, band_status: 'NO_THRESHOLD',
      threshold: null,
      policy_outcome:   'BLOCKED',
      policy_sub_tier:  null,
      policy_rationale: `FAO-REC-002 ${asset}: no materiality threshold configured for scope=Spot. Asset BLOCKED pending Controller setup. Cannot evaluate.`,
      hitl_status:      'NOT_REQUIRED',
      obligations:      [],
      status:           'FAILURE',
      error_details:    `Asset ${asset} not present in materiality_thresholds (scope=Spot)`
    }) });
    continue;
  }

  const discrepancy = w - l;

  // ----- Decision matrix --------------------------------------------------
  let outcome, sub_tier, rationale, hitl_status, obligations = [];
  let ratio = null;
  let band_status;

  if (l < 0) {
    // (1) Negative liability — FAO-REC-007 (krakendb precedent)
    band_status      = 'NEGATIVE_LEDGER';
    outcome          = 'REQUIRE_HUMAN';
    sub_tier         = 'CRITICAL';
    hitl_status      = 'PENDING';
    rationale        = `FAO-REC-007 ${asset} negative liability detected (ledger=${l}). Cannot compute meaningful ratio. Routed to CRITICAL HITL — Controller + CFO review required (RED tier, 2 approvers). Pattern flagged in krakendb 2014 reference implementation as operational concern.`;
  } else if (l === 0) {
    // (2) Zero ledger — division undefined
    band_status      = 'ZERO_LEDGER';
    outcome          = 'REQUIRE_HUMAN';
    sub_tier         = 'STANDARD';
    hitl_status      = 'PENDING';
    rationale        = `FAO-REC-006 ${asset} zero ledger balance with non-zero wallet (${w}). Cannot compute reserve ratio. Manual review required.`;
  } else {
    ratio = w / l;

    if (ratio < t.ratio_floor) {
      // (3) Under-reserved — the worst case
      band_status   = 'BELOW_FLOOR';
      outcome       = 'REQUIRE_HUMAN';
      sub_tier      = 'CRITICAL';
      hitl_status   = 'PENDING';
      rationale     = `FAO-REC-004 ${asset} ratio ${ratio.toFixed(6)} below floor ${t.ratio_floor.toFixed(4)}. UNDER-RESERVED — wallet holdings insufficient to cover ledger liabilities. Routed to CRITICAL HITL (RED tier, 2 approvers).`;
    } else if (ratio > t.ratio_band_upper) {
      // (4) Unexpected surplus — investigate ledger
      band_status   = 'ABOVE_BAND_UPPER';
      outcome       = 'REQUIRE_HUMAN';
      sub_tier      = 'STANDARD';
      hitl_status   = 'PENDING';
      rationale     = `FAO-REC-006 ${asset} ratio ${ratio.toFixed(6)} above expected band upper ${t.ratio_band_upper.toFixed(4)}. Unexpected surplus — possible ledger under-recording. Investigate liability side.`;
    } else if (t.asset_class === 'Stablecoin' && Math.abs(discrepancy) > t.materiality_usd) {
      // (5) Stablecoin USD materiality breach (units == USD for stablecoins)
      band_status   = 'IN_BAND_USD_MATERIAL';
      outcome       = 'REQUIRE_HUMAN';
      sub_tier      = 'STANDARD';
      hitl_status   = 'PENDING';
      rationale     = `FAO-REC-002 ${asset} stablecoin: ratio ${ratio.toFixed(6)} within band [${t.ratio_band_lower.toFixed(4)}, ${t.ratio_band_upper.toFixed(4)}], BUT absolute discrepancy $${Math.abs(discrepancy).toFixed(2)} exceeds materiality threshold $${t.materiality_usd.toFixed(2)}. Stablecoin units are 1:1 USD; small ratio deviations on large pools are still material.`;
    } else if (ratio < t.ratio_band_lower) {
      // (6) Drift below expected band — not under-reserved (above floor)
      //     but reserve ratio is lower than expected over-reservation posture
      band_status   = 'BELOW_BAND_LOWER';
      outcome       = 'ALLOW_WITH_OBLIGATIONS';
      sub_tier      = null;
      hitl_status   = 'NOT_REQUIRED';
      obligations   = ['weekly_review_required', 'flag_drift_pattern_to_controller'];
      rationale     = `FAO-REC-006 ${asset} ratio ${ratio.toFixed(6)} below expected band lower ${t.ratio_band_lower.toFixed(4)} but above floor ${t.ratio_floor.toFixed(4)}. Reserves cover liabilities but over-reservation posture has drifted. Allowed with weekly-review obligation.`;
    } else {
      // (7) In expected band — clean
      band_status   = 'IN_BAND';
      outcome       = 'ALLOW';
      sub_tier      = null;
      hitl_status   = 'NOT_REQUIRED';
      rationale     = `FAO-REC-006 ${asset} ratio ${ratio.toFixed(6)} within expected band [${t.ratio_band_lower.toFixed(4)}, ${t.ratio_band_upper.toFixed(4)}]. Reserved as expected.`;
    }
  }

  output_items.push({ json: build_writer_payload(ctx, {
    asset, wallet: w, ledger: l,
    ratio, discrepancy, band_status,
    threshold: {
      asset_class:      t.asset_class,
      ratio_floor:      t.ratio_floor,
      ratio_band_lower: t.ratio_band_lower,
      ratio_band_upper: t.ratio_band_upper,
      materiality_usd:  t.materiality_usd
    },
    policy_outcome:   outcome,
    policy_sub_tier:  sub_tier,
    policy_rationale: rationale,
    hitl_status:      hitl_status,
    obligations:      obligations,
    status:           'SUCCESS',
    error_details:    null
  }) });
}

return output_items;

// ----- Helper: build writer payload from context + per-asset facts ----------
function build_writer_payload(ctx, facts) {
  return {
    correlation_id:      ctx.correlation_id,
    execution_id:        ctx.execution_id,
    agent_id:            ctx.agent_id,
    risk_tier:           ctx.risk_tier,
    inputs: {
      event_type:  'ASSET_RECONCILED',
      asset:       facts.asset,
      wallet:      facts.wallet,
      ledger:      facts.ledger,
      ratio:       facts.ratio,
      discrepancy: facts.discrepancy,
      band_status: facts.band_status,
      threshold:   facts.threshold
    },
    ai_prompt:           null,
    ai_output:           null,
    ai_confidence:       null,
    fractional_cost_usd: null,
    policy_outcome:      facts.policy_outcome,
    policy_sub_tier:     facts.policy_sub_tier,
    policy_rationale:    facts.policy_rationale,
    obligations:         facts.obligations || [],
    hitl_status:         facts.hitl_status,
    hitl_approver_id:    null,
    status:              facts.status,
    error_details:       facts.error_details
  };
}

// ============================================================================
// FAO Reserve Reconciliation Agent — Aggregate Rollup
// ----------------------------------------------------------------------------
// Reaches back to Per-Asset Reconcile to read the 7 per-asset decisions
// (the items flowing IN to this node are the inserted shadow_ledger rows
// returned by Writer, not the original decisions). Computes the execution-
// level rollup outcome using "worst per-asset outcome wins":
//
//   - any REQUIRE_HUMAN → execution = REQUIRE_HUMAN
//   - any DENY/BLOCKED  → execution = matching outcome
//   - any ALLOW_WITH_OBLIGATIONS (and no worse) → execution = ALLOW_WITH_OBLIGATIONS
//   - otherwise → ALLOW
//
// Outputs a single item formatted as a Writer payload for the COMMITTED
// event. The IF node downstream gates whether this gets written: COMMITTED
// is only logged when the execution completes without HITL routing. For
// REQUIRE_HUMAN outcomes, the chain ends at the per-asset rows tonight; the
// HITL Gateway sub-workflow (Apr 25) will extend the chain through approval
// to a final COMMITTED event then.
// ============================================================================

const ctx        = $('Init Execution').first().json;
const per_asset_items = $('Per-Asset Reconcile').all();
const per_asset = per_asset_items.map(it => it.json);

// Outcome ranking — higher number = worse outcome
const rank = {
  'ALLOW':                  0,
  'ALLOW_WITH_OBLIGATIONS': 1,
  'REQUIRE_HUMAN':          2,
  'DENY':                   3,
  'BLOCKED':                4
};

let rollup_outcome      = 'ALLOW';
let rollup_sub_tier     = null;
let worst_rank          = 0;
let aggregated_obligations = new Set();

const per_asset_summary = per_asset.map(row => {
  const r = rank[row.policy_outcome] ?? 0;
  if (r > worst_rank) {
    worst_rank      = r;
    rollup_outcome  = row.policy_outcome;
    rollup_sub_tier = row.policy_sub_tier;
  } else if (r === worst_rank && row.policy_sub_tier === 'CRITICAL') {
    // Within same outcome rank, CRITICAL escalates STANDARD
    rollup_sub_tier = 'CRITICAL';
  }
  for (const o of (row.obligations || [])) aggregated_obligations.add(o);
  return {
    asset:           row.inputs.asset,
    band_status:     row.inputs.band_status,
    ratio:           row.inputs.ratio,
    policy_outcome:  row.policy_outcome,
    policy_sub_tier: row.policy_sub_tier
  };
});

const counts = {
  ALLOW:                  per_asset.filter(r => r.policy_outcome === 'ALLOW').length,
  ALLOW_WITH_OBLIGATIONS: per_asset.filter(r => r.policy_outcome === 'ALLOW_WITH_OBLIGATIONS').length,
  REQUIRE_HUMAN:          per_asset.filter(r => r.policy_outcome === 'REQUIRE_HUMAN').length,
  DENY:                   per_asset.filter(r => r.policy_outcome === 'DENY').length,
  BLOCKED:                per_asset.filter(r => r.policy_outcome === 'BLOCKED').length
};

const rationale_parts = [
  `FAO-REC-001 execution rollup over ${per_asset.length} assets.`,
  `Outcomes: ${counts.ALLOW} ALLOW, ${counts.ALLOW_WITH_OBLIGATIONS} ALLOW_WITH_OBLIGATIONS, ${counts.REQUIRE_HUMAN} REQUIRE_HUMAN${counts.DENY ? ', ' + counts.DENY + ' DENY' : ''}${counts.BLOCKED ? ', ' + counts.BLOCKED + ' BLOCKED' : ''}.`,
  `Worst-asset rule applied: execution outcome = ${rollup_outcome}${rollup_sub_tier ? ' (' + rollup_sub_tier + ')' : ''}.`
];

const escalated_assets = per_asset.filter(r => rank[r.policy_outcome] >= 2);
if (escalated_assets.length > 0) {
  rationale_parts.push(
    `Escalated assets: ${escalated_assets.map(r => r.inputs.asset + ' (' + r.policy_outcome + (r.policy_sub_tier ? '/' + r.policy_sub_tier : '') + ')').join(', ')}.`
  );
}

// HITL routing: if execution requires human, the COMMITTED event is held
// until HITL resolves. Tonight the chain ends here for REQUIRE_HUMAN
// (HITL Gateway sub-workflow lands Apr 25).
const hitl_status = (rollup_outcome === 'REQUIRE_HUMAN') ? 'PENDING' : 'NOT_REQUIRED';
const status      = (rollup_outcome === 'BLOCKED' || rollup_outcome === 'DENY') ? 'FAILURE' : 'SUCCESS';

return [{
  json: {
    correlation_id:      ctx.correlation_id,
    execution_id:        ctx.execution_id,
    agent_id:            ctx.agent_id,
    risk_tier:           ctx.risk_tier,
    inputs: {
      event_type:        'COMMITTED',
      per_asset_summary: per_asset_summary,
      counts:            counts,
      escalated_assets:  escalated_assets.map(r => r.inputs.asset)
    },
    ai_prompt:           null,
    ai_output:           null,
    ai_confidence:       null,
    fractional_cost_usd: null,
    policy_outcome:      rollup_outcome,
    policy_sub_tier:     rollup_sub_tier,
    policy_rationale:    rationale_parts.join(' '),
    obligations:         Array.from(aggregated_obligations),
    hitl_status:         hitl_status,
    hitl_approver_id:    null,
    status:              status,
    error_details:       null,

    // Internal field for IF node — not a shadow_ledger column
    _rollup_outcome:     rollup_outcome
  }
}];
